insert into public.battlecards (id, client_id, competitor_id, analysis_run_id, version, title, summary, status, author_type, published_at) values
  ('bd71484c-2992-506b-b5e6-c42ffa213a5d', 'e73b171e-e444-5965-8bcc-a6dcd641bda4', 'a36d8ea4-497d-55b1-98b1-a706d4829d7b', '41c0e8ad-d5bd-5d40-8a2a-d17978c7113a', 2, 'Lumenary AI vs Clarity LLM', 'Clarity LLM won 3 deals worth $897,000 over the last four quarters. The top root causes are no soc 2 type ii and eu data residency gaps and token pricing uncompetitive above 50m tokens/month.', 'published', 'agent', '2026-10-10T09:00:00Z'),
  ('7763d0f8-eb03-5701-aa4e-977bd7a740b8', '022d4616-aa13-5485-9320-f737f67b9184', '2b6ff8aa-271e-5e77-9c79-4e5b1518ff61', '6ae449df-e4e5-5c1b-b4f5-775077c24572', 2, 'Helpwise AI vs Supportiva', 'Supportiva won 10 deals worth $1,445,000 over the last four quarters. The top root causes are no voice channel in the autonomous agent and per-resolution pricing misaligned with high-volume smb.', 'published', 'agent', '2026-10-10T09:00:00Z'),
  ('a6904b2b-fe01-511c-a9f0-001298bf64d9', 'ee81bcee-70cd-5ed7-9c78-247076039d58', '34c980d4-edb4-50a6-9a30-e4cd16e05785', 'a8dc9a0c-ad38-500e-87b8-2d6f301251c3', 2, 'Codexa vs Buildbot', 'Buildbot won 9 deals worth $1,299,000 over the last four quarters. The top root causes are suggestion latency above 800ms on large monorepos and no agentic multi-file edits.', 'published', 'agent', '2026-10-10T09:00:00Z'),
  ('5066e5c8-5f4e-5dcf-9c0b-1ae023dcb8ea', '0ed60342-1aff-5bda-ada2-85e4d994be90', 'c3fbbcdb-82b0-5c81-a8d4-4918230b9fc5', '6bab55b9-21b8-575e-9663-0dfcc19cacc9', 2, 'Pipelinr vs Outreachly', 'Outreachly won 10 deals worth $918,000 over the last four quarters. The top root causes are gdpr-compliant outreach missing for eu prospects and generic ai messaging loses enterprise replies.', 'published', 'agent', '2026-10-10T09:00:00Z'),
  ('0c5e91a7-f644-5fa7-8740-5d75ad552407', 'c278593f-34a4-5fe1-b63b-db1a59a471fb', 'd34cdf18-734f-583d-ac8b-d1a2e413da0f', 'f16d7e69-037e-5083-87e1-64c026043610', 2, 'Neuraflow vs Agentwise', 'Agentwise won 6 deals worth $371,000 over the last four quarters. The top root causes are no soc 2 type ii certification and perceived vendor risk as a 2023 startup.', 'published', 'agent', '2026-10-10T09:00:00Z')
